(function(){
'use strict';

function clearInjectedTeamBlocks(){
  const mount=document.getElementById('tp-results-2026-mount');
  if(mount)mount.remove();
  const summary=document.getElementById('tp-final-summary');
  if(summary)summary.style.display='';
}

function wrapStandardTeamProfile(){
  const original=window.openTeamProfile;
  if(typeof original!=='function'||original.__cffRoutingHotfix)return;
  async function wrapped(){
    const result=await original.apply(this,arguments);
    clearInjectedTeamBlocks();
    return result;
  }
  wrapped.__cffRoutingHotfix=true;
  wrapped.__cffOriginal=original;
  window.openTeamProfile=wrapped;
}

function showResultsLoading(){
  const modal=document.getElementById('results-modal');
  const title=document.getElementById('results-modal-title');
  const body=document.querySelector('#table-team-results tbody');
  if(title)title.textContent=`Resultados: ${String(typeof currentTeamView!=='undefined'?currentTeamView:'Equipe')}`;
  if(body)body.innerHTML='<tr><td colspan="4" style="padding:28px;text-align:center;color:#8ea7bf;">Carregando resultados...</td></tr>';
  if(modal)modal.classList.add('active');
}

async function openResultsModalSafe(){
  showResultsLoading();
  try{
    const tasks=[];
    if(typeof loadResults==='function')tasks.push(Promise.resolve().then(()=>loadResults()));
    if(typeof loadTeamAliases==='function')tasks.push(Promise.resolve().then(()=>loadTeamAliases()));
    if(typeof loadNovosTorneios==='function'&&!(typeof novosTorneiosLoaded!=='undefined'&&novosTorneiosLoaded))tasks.push(Promise.resolve().then(()=>loadNovosTorneios()));
    await Promise.allSettled(tasks);
    if(typeof renderTeamResults!=='function')throw new Error('Renderizador de resultados indisponível');
    renderTeamResults();
    const title=document.getElementById('results-modal-title');
    if(title)title.textContent=`Resultados: ${String(typeof currentTeamView!=='undefined'?currentTeamView:'Equipe')}`;
  }catch(error){
    console.error('[Resultados da equipe]',error);
    const body=document.querySelector('#table-team-results tbody');
    if(body)body.innerHTML='<tr><td colspan="4" style="padding:28px;text-align:center;color:#8ea7bf;">Não foi possível carregar os resultados agora. Atualize a página e tente novamente.</td></tr>';
  }
}

window.openResultsModal=openResultsModalSafe;
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',wrapStandardTeamProfile,{once:true});else wrapStandardTeamProfile();
})();
